test("同じ親の兄弟を 2 つ包むと、いちばん前面にいたものの位置に新しい Box が入り、選んだものがその子になる", () => {
  const grouped = Result.unwrap(
    DesignDocument.groupIntoBox(setupDocument(), ["x", "b"], "box"),
  );

  expect([childNames(grouped, "home"), childNames(grouped, "box")]).toEqual([
    ["a", "box", "y", "group"],
    ["x", "b"],
  ]);
});

test("離れた兄弟を包むと、間にいた選んでいない兄弟は Box より背面側に残る", () => {
  const grouped = Result.unwrap(
    DesignDocument.groupIntoBox(setupDocument(), ["a", "b"], "box"),
  );

  expect(childNames(grouped, "home")).toEqual(["x", "box", "y", "group"]);
});

test("前面にいるものから順に名前を渡しても、Box の子は元の並び順になる", () => {
  const grouped = Result.unwrap(
    DesignDocument.groupIntoBox(setupDocument(), ["y", "a", "b"], "box"),
  );

  expect(childNames(grouped, "box")).toEqual(["a", "b", "y"]);
});

test("親が違うノードは包めない", () => {
  const document = setupDocument();

  expect([
    Result.isOk(DesignDocument.groupIntoBox(document, ["a"], "box")),
    Result.isOk(DesignDocument.groupIntoBox(document, ["inner-1"], "box")),
    DesignDocument.groupIntoBox(document, ["a", "inner-1"], "box"),
  ]).toStrictEqual([true, true, Result.err({ kind: "different-parents" })]);
});

test("artboard とその子は包めない", () => {
  expect(
    DesignDocument.groupIntoBox(setupDocument(), ["a", "home"], "box"),
  ).toStrictEqual(Result.err({ kind: "node-not-found", name: "home" }));
});

test("ドキュメントに無い名前が混ざると、Box 名が使えなくても node-not-found になる", () => {
  expect(
    DesignDocument.groupIntoBox(setupDocument(), ["a", "missing"], "Box 1"),
  ).toStrictEqual(Result.err({ kind: "node-not-found", name: "missing" }));
});

test("既に使われている名前の Box では、兄弟をまとめて包めない", () => {
  expect(
    DesignDocument.groupIntoBox(setupDocument(), ["a", "b"], "group"),
  ).toStrictEqual(Result.err({ kind: "duplicate-name", name: "group" }));
});

test("同じ名前を 2 回渡すと、そのノード 1 つを包んだのと同じになる", () => {
  const document = setupDocument();

  expect(
    DesignDocument.groupIntoBox(document, ["b", "b"], "box"),
  ).toStrictEqual(DesignDocument.groupIntoBox(document, ["b"], "box"));
});

test("隣り合うフローの兄弟を包んでから外すと、元の並びに戻る", () => {
  const document = setupDocument();
  const grouped = Result.unwrap(
    DesignDocument.groupIntoBox(document, ["x", "b"], "box"),
  );

  const { document: ungrouped } = Result.unwrap(
    DesignDocument.ungroupBox(grouped, "box"),
  );

  expect(ungrouped).toEqual(document);
});

test("layout: row の親の中のフローの兄弟を包むと、Box も row で並べる", () => {
  const grouped = groupPair(setupDocument({ layout: "row" }, FlowPair));

  expect(propsOf(grouped, "box")).toEqual({ layout: "row" });
});

test("artboard の直下のフローの兄弟を包むと、artboard に書かれた layout / gap を Box が持つ", () => {
  const document = DesignDocument.create({
    tokens: DocumentTemplate.Default.tokens,
    artboards: [
      {
        name: "screen",
        width: 375,
        height: 812,
        props: { layout: "row", gap: "sm" },
        children: FlowPair,
      },
    ],
  });

  const grouped = groupPair(document);

  expect(propsOf(grouped, "box")).toEqual({ layout: "row", gap: "sm" });
});

test("親に何も書かれていなければ、フローで fill を持たない兄弟を包んだ Box は props を持たない", () => {
  const grouped = groupPair(setupDocument({}, FlowPair));
  const box = Option.unwrap(DesignDocument.findNode(grouped, "box"));

  expect("props" in box).toBe(false);
});

test("兄弟のうち 1 つでも幅が fill なら Box の幅も fill になり、下限・上限は写さない", () => {
  const filled = groupPair(
    setupDocument({}, [
      {
        name: "first",
        type: "Text",
        props: { widthMode: "fill", minWidth: 120, maxWidth: 320 },
      },
      { name: "second", type: "Text" },
    ]),
  );
  const unfilled = groupPair(
    setupDocument({}, [
      { name: "first", type: "Text", props: { widthMode: "hug" } },
      { name: "second", type: "Text" },
    ]),
  );

  expect([propsOf(filled, "box"), propsOf(unfilled, "box")]).toEqual([
    { widthMode: "fill" },
    {},
  ]);
});

test("絶対配置の兄弟をまとめて包むと、Box はそれらの各軸の最小の座標に絶対配置で置かれる", () => {
  const grouped = groupPair(
    setupDocument({}, [
      {
        name: "first",
        type: "Text",
        props: { placement: "absolute", x: 40, y: 10 },
      },
      {
        name: "second",
        type: "Text",
        props: { placement: "absolute", x: 20, y: 30 },
      },
    ]),
  );

  expect(propsOf(grouped, "box")).toEqual({
    placement: "absolute",
    x: 20,
    y: 10,
  });
});

test("絶対配置の兄弟をまとめて包むと、兄弟は絶対配置のまま Box の座標を引いた位置になる", () => {
  const grouped = groupPair(
    setupDocument({}, [
      {
        name: "first",
        type: "Text",
        props: { placement: "absolute", x: 40, y: 10 },
      },
      {
        name: "second",
        type: "Text",
        props: { placement: "absolute", x: 20, y: 30 },
      },
    ]),
  );

  expect([propsOf(grouped, "first"), propsOf(grouped, "second")]).toEqual([
    { placement: "absolute", x: 20, y: 0 },
    { placement: "absolute", x: 0, y: 20 },
  ]);
});

test("絶対配置の兄弟の追従が軸ごとに揃っていれば Box も同じ追従を持ち、揃っていない軸は持たない", () => {
  const grouped = groupPair(
    setupDocument({}, [
      {
        name: "first",
        type: "Text",
        props: {
          placement: "absolute",
          x: 0,
          y: 0,
          constraintX: "max",
          constraintY: "center",
        },
      },
      {
        name: "second",
        type: "Text",
        props: {
          placement: "absolute",
          x: 0,
          y: 0,
          constraintX: "max",
          constraintY: "stretch",
        },
      },
    ]),
  );

  expect(propsOf(grouped, "box")).toEqual({
    placement: "absolute",
    x: 0,
    y: 0,
    constraintX: "max",
  });
});

test("絶対配置の兄弟をまとめて包んでから外すと、元の座標と追従に戻る", () => {
  const document = setupDocument({}, [
    {
      name: "first",
      type: "Text",
      props: { placement: "absolute", x: 40, y: 10, constraintX: "max" },
    },
    {
      name: "second",
      type: "Text",
      props: { placement: "absolute", x: 20, y: 30, constraintY: "center" },
    },
  ]);

  const { document: ungrouped } = Result.unwrap(
    DesignDocument.ungroupBox(groupPair(document), "box"),
  );

  expect(ungrouped).toEqual(document);
});

test("絶対配置とフローの兄弟が混ざっていると包めない", () => {
  const absoluteFirst: Node = {
    name: "first",
    type: "Text",
    props: { placement: "absolute", x: 40, y: 10 },
  };
  const mixed = setupDocument({}, [absoluteFirst, FlowPair[1]]);
  const flow = setupDocument({}, FlowPair);

  expect([
    DesignDocument.groupIntoBox(mixed, ["first", "second"], "box"),
    Result.isOk(DesignDocument.groupIntoBox(flow, ["first", "second"], "box")),
  ]).toStrictEqual([Result.err({ kind: "mixed-placement" }), true]);
});

test("絶対配置とフローの兄弟が混ざっていると、Box 名が使えなくても mixed-placement になる", () => {
  const absoluteFirst: Node = {
    name: "first",
    type: "Text",
    props: { placement: "absolute", x: 40, y: 10 },
  };
  const mixed = setupDocument({}, [absoluteFirst, FlowPair[1]]);

  expect(
    DesignDocument.groupIntoBox(mixed, ["first", "second"], "Box 1"),
  ).toStrictEqual(Result.err({ kind: "mixed-placement" }));
});

test("部品インスタンスと絶対配置の兄弟が混ざっていると包めない", () => {
  const document = setupDocument({}, [
    {
      name: "first",
      type: "Text",
      props: { placement: "absolute", x: 40, y: 10 },
    },
    { name: "second", ref: "primary-button" },
  ]);

  expect(
    DesignDocument.groupIntoBox(document, ["first", "second"], "box"),
  ).toStrictEqual(Result.err({ kind: "mixed-placement" }));
});

test("ドキュメントに無い名前と親の違うノードが同時に混ざると、無い名前の node-not-found になる", () => {
  expect(siblingsOf(["inner-1", "missing", "a"])).toStrictEqual(
    Result.err({ kind: "node-not-found", name: "missing" }),
  );
});

test("ドキュメントに無い名前が 2 つ混ざると、渡された順で最初の名前の node-not-found になる", () => {
  expect(siblingsOf(["m1", "b", "m2"])).toStrictEqual(
    Result.err({ kind: "node-not-found", name: "m1" }),
  );
});

test("同じ位置が 2 回渡されても、位置は 1 つにまとまる", () => {
  expect(
    Option.unwrap(
      SiblingPositions.fromChildPositions([
        { parentName: "home", index: 1 },
        { parentName: "home", index: 1 },
      ]),
    ),
  ).toEqual({ parentName: "home", indices: [1] });
});

test("離れた兄弟を抜いた並びでは、位置がいちばん大きかった兄弟の位置は、それより小さい位置で抜けた数だけ小さくなる", () => {
  expect(
    SiblingPositions.lastAfterRemoving({
      parentName: "home",
      indices: [1, 3],
    }),
  ).toEqual({ parentName: "home", index: 2 });
});

test("親に並べ方が書かれていても、その中の 1 つだけを包んだ Box は親の並べ方を写さず props を持たない", () => {
  const document = DesignDocument.create({
    tokens: DocumentTemplate.Default.tokens,
    artboards: [
      {
        name: "screen",
        width: 375,
        height: 812,
        children: [
          {
            name: "panel",
            type: "Box",
            props: { layout: "row", gap: "md", align: "center" },
            children: [{ name: "title", type: "Text" }],
          },
        ],
      },
    ],
  });

  const grouped = Result.unwrap(
    DesignDocument.groupIntoBox(document, ["title"], "box"),
  );
  const box = Option.unwrap(DesignDocument.findNode(grouped, "box"));

  expect(Node.isPrimitive(box) && box.props).toBeUndefined();
});

test("同じ親の兄弟を複数選んでグループ化すると、選んだものが新しい Box の子になる", () => {
  const grouped = Option.unwrap(groupSelecting(["b", "a"]));

  expect(childNames(grouped, "box")).toEqual(["a", "b"]);
});

test("まとめてグループ化すると、選択が新しい Box 1 つへ移る", () => {
  const grouped = Option.unwrap(groupSelecting(["a", "b"]));

  expect(
    DocumentSelection.names(EditorState.documentSelection(grouped)),
  ).toEqual(["box"]);
});

test("親が違うノードを選んでいるとグループ化できない", () => {
  expect([
    Option.isSome(groupSelecting(["a"])),
    Option.isSome(groupSelecting(["inner"])),
    Option.isSome(groupSelecting(["a", "inner"])),
  ]).toEqual([true, true, false]);
});

test("絶対配置とフローのノードが混ざっているとグループ化できない", () => {
  expect([
    Option.isSome(groupSelecting(["badge"])),
    Option.isSome(groupSelecting(["a", "badge"])),
  ]).toEqual([true, false]);
});

test("まとめてグループ化したあと、1 回の取り消しで元の並びに戻る", () => {
  const grouped = Option.unwrap(groupSelecting(["a", "b"]));

  const undone = Option.unwrap(EditorState.undo(grouped));

  expect(childNames(undone, "home")).toEqual(["a", "b", "badge", "group"]);
});

test("まとめてグループ化した直後に解除すると、包んだものがまとめて選ばれる", () => {
  const grouped = Option.unwrap(groupSelecting(["b", "a"]));

  const ungrouped = Option.unwrap(EditorState.ungroupSelected(grouped));

  expect(
    DocumentSelection.names(EditorState.documentSelection(ungrouped)),
  ).toEqual(["a", "b"]);
});

test("同じ親の兄弟を複数選んでいるときは、複製・コピー・グループ化・動かせる向きの並べ替え・削除が押せる", () => {
  const menu = EditMenu.create(
    EditorState.selectNodes(setupState(), ["title", "panel"]),
    EditMenuTargets.Node,
  );

  expect(enabledOperations(menu)).toEqual([
    EditOperations.Duplicate,
    EditOperations.Copy,
    EditOperations.Group,
    EditOperations.BringForward,
    EditOperations.Delete,
  ]);
});

test("親が違うノードを複数選んでいるときは、複製・コピー・削除だけが押せ、グループ化と並べ替えは押せない", () => {
  const menu = EditMenu.create(
    EditorState.selectNodes(stateWithNestedPanel(), ["title", "inner-a"]),
    EditMenuTargets.Node,
  );

  expect(enabledOperations(menu)).toEqual([
    EditOperations.Duplicate,
    EditOperations.Copy,
    EditOperations.Delete,
  ]);
});

test("同じ部品のインスタンスをまとめて選んで ⌘G を押すと、2 つが新しい Box の子になる", async () => {
  await renderWithSameComponentInstancesSelected();

  await userEvent.keyboard("{Meta>}g{/Meta}");

  expect(rowNames(tree())).toEqual([
    "home-title",
    "box",
    "home-login",
    "home-signup",
  ]);
});

test("複数選択の一員の行のメニューの Group を押すと、選んだものが新しい Box の子になる", async () => {
  await renderWithSameComponentInstancesSelected();

  rightClickInTree("home-signup");
  await userEvent.click(menuRow("Group"));

  expect(rowNames(tree())).toEqual([
    "home-title",
    "box",
    "home-login",
    "home-signup",
  ]);
});

test("different-parents は、同じ親を持たないことを述べるメッセージになる", () => {
  expect(DesignDocumentEditError.message({ kind: "different-parents" })).toBe(
    "nodes do not share the same parent",
  );
});

test("写せない要素があれば、並びで最初に写せなかった要素の失敗になる", () => {
  expect(
    ArrayEx.mapNonEmptyUntilErr([1, -2, -3], (item) =>
      item > 0 ? Result.ok(item) : Result.err(item),
    ),
  ).toEqual(Result.err(-2));
});

groupIntoBox(
  document: DesignDocument,
  names: NonEmptyArray<string>,
  boxName: string,
): Result<DesignDocument, DesignDocumentEditError> {
  const siblings = DesignDocument.findSiblingPositions(document, names);
  if (!Result.isOk(siblings)) {
    return siblings;
  }
  const { parentName, indices } = siblings.value;
  const parent = writtenParentOf(document, parentName);
  if (!Result.isOk(parent)) {
    return parent;
  }
  const members = childrenAt(parent.value.children, indices);
  if (!Result.isOk(members)) {
    return members;
  }
  const [sole, ...rest] = members.value;
  const box =
    rest.length === 0
      ? Result.ok(groupedBox(sole, boxName))
      : groupedSiblingsBox(members.value, parent.value.props, boxName);
  if (!Result.isOk(box)) {
    return box;
  }
  const unusable = unusableNameError(document, boxName);
  if (Option.isSome(unusable)) {
    return Result.err(unusable.value);
  }
  const at = SiblingPositions.lastAfterRemoving(siblings.value);
  return updateChildrenOfParent(document, parentName, (tree) => {
    const remaining = members.value.reduce(
      (current, member) => NodeTree.spliceByName(current, member.name, []),
      tree,
    );
    return NodeTree.insertAt(remaining, at.index, box.value);
  });
},
